function mountMap(){if(leaflet){leaflet.remove();leaflet=null;}const el=document.querySelector('#corporate-real-map');if(!el)return;const L=window.L,msg=document.querySelector('#tile-message');if(!L){msg.textContent='地図ライブラリ未取得。現場の「ここへ行く」から外部地図を利用できます。';return;}leaflet=L.map(el,{zoomControl:true,scrollWheelZoom:true,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false}).setView([37.47,140.38],9);const tiles=L.tileLayer('https://cyberjapandata.gsi.go.jp/xyz/pale/{z}/{x}/{y}.png',{maxZoom:18,attribution:'<a href="https://maps.gsi.go.jp/development/ichiran.html" target="_blank" rel="noopener">地理院タイル</a>'}).addTo(leaflet);let tileErrors=false;tiles.on('tileerror',()=>{tileErrors=true;msg.hidden=false;msg.textContent='背景地図を取得できません。通信を確認してください。位置未登録の現場は一覧へ。';});tiles.on('load',()=>{if(!tileErrors)msg.hidden=true;});const bounds=[];for(const [i,s]of mapRows().entries()){const c=locationOf(s);if(!c)continue;bounds.push([c.lat,c.lon]);const marker=L.marker([c.lat,c.lon],{icon:L.divIcon({className:'real-number-pin',html:(m=>`<button aria-label="${esc(s.name)}" class="${s.id===selected?'selected':''}">${i+1}${m?`<span class="pin-mark${m==='！'?' is-warn':''}">${m}</span>`:''}</button>`)(pinMark(api.data(),s,layer)),iconSize:[40,44],iconAnchor:[20,40]})}).addTo(leaflet);marker.on('click',()=>selectSite(s.id,true));}const chosen=api.data().sites.find(s=>s.id===selected),c=chosen&&locationOf(chosen);if(c)leaflet.setView([c.lat,c.lon],13,{animate:false});else if(bounds.length)leaflet.fitBounds(bounds,{padding:[35,35],maxZoom:13,animate:false});const current=leaflet;setTimeout(()=>{if(leaflet===current&&el.isConnected)current.invalidateSize({pan:false});},0);}
