function inspect(id,schedule=null){const d=api.data(),s=d.sites.find(s=>s.id===id);if(!s)return;selected=id;const plan=schedule||eventsFor(d).find(e=>e.siteId===id&&e.kind==='点検'&&!e.done);const saved=d.visitDrafts?.[id]||(d.visits||[]).findLast(v=>v.siteId===id&&v.status==='draft');if(schedule&&saved?.scheduleId&&(saved.scheduleId!==schedule.id||(saved.scheduleSource||'inspections')!==schedule.source)){const other=eventsFor(d).find(e=>e.id===saved.scheduleId&&e.source===(saved.scheduleSource||'inspections'));api.modal('別の予定の下書きがあります',`<p>この拠点には「${esc(other?.title||'別の予定')} ${esc(other?.date||'')} ${esc(other?.time||'')}」の下書きがあります。選んだ予定へ付け替えることはしません。</p><p>下書きを完了または保存してから、選んだ予定の点検を始めてください。</p><button data-inspect-site="${esc(id)}">下書きを再開 ›</button>`);return;}visitBack=['inspections','record','home','calendar','route'].includes(document.body.dataset.page)?document.body.dataset.page:'map';draft=structuredClone(saved||{id:uid(),siteId:id,scheduleId:plan?.id||'',scheduleSource:plan?.source||'',personId:plan?.personId||s.assigneeId||'',checks:{},values:{},photos:[],photoLinks:[],equipmentIds:[],note:'',readings:{},status:'draft'});draft.photoLinks??=[];if(schedule&&!draft.scheduleId){draft.scheduleId=schedule.id;draft.scheduleSource=schedule.source;}activeKind=siteEquipment(d,s)[0]?.kind||'';visitView={tier:'最重要',parent:null,editor:null,page:0};api.go('visit');}
// 点検記録の1項目を決める（フォームの隠し欄に入れてから、いつもの capture で下書きに反映）
function setCheck(key,value,way,reason){const f=document.querySelector('#solvia-visit');if(!f)return;const q=a=>f.querySelector(`[${a}="${CSS.escape(key)}"]`);if(q('data-check'))q('data-check').value=value;if(q('data-issue-way'))q('data-issue-way').value=way;if(q('data-exclusion-reason'))q('data-exclusion-reason').value=reason;capture();}
// 下書き：画面に出ていない項目（設定で隠した・別の鍵になった）の結果も消さずに残す
function capture(){const f=document.querySelector('#solvia-visit');if(!f||!draft)return;const fd=new FormData(f);draft.checks={...(draft.checks||{}),...Object.fromEntries([...f.querySelectorAll('[data-check]')].map(e=>[e.dataset.check,e.value]))};for(const key of ['note','personId','newIssue','noEquipmentReason','photoEquipment'])draft[key]=String(fd.get(key)||'');draft.values={note:fd.get('valuesNote')||''};draft.equipmentIds=fd.getAll('equipmentIds');draft.readings=Object.fromEntries(['soc','temp','power'].map(k=>[k,fd.get('reading-'+k)]).filter(([,v])=>v!==null&&String(v).trim()!=='').map(([k,v])=>[k,Number(v)]));draft.exclusionReasons={...(draft.exclusionReasons||{}),...Object.fromEntries([...f.querySelectorAll('[data-exclusion-reason]')].map(e=>[e.dataset.exclusionReason,e.value]))};draft.unavailableReasons=Object.fromEntries(['soc','temp'].map(k=>[k,String(fd.get('unavailable-'+k)||'')]));draft.readingConfirmed=fd.has('readingConfirmed');draft.issueWays=Object.fromEntries(Object.entries({...(draft.issueWays||{}),...Object.fromEntries([...f.querySelectorAll('[data-issue-way]')].map(e=>[e.dataset.issueWay,e.value]))}).filter(([k,v])=>v&&draft.checks[k]==='不具合あり'));for(const el of f.querySelectorAll('[data-exclusion-reason]'))el.hidden=draft.checks[el.dataset.exclusionReason]!=='対象外';visitProgress();}
function visitProgress(){const el=document.querySelector('#visit-progress');if(!el||!draft)return;const d=api.data(),s=d.sites.find(s=>s.id===draft.siteId),checks=checksFor(d,s),progress=visitProgressStats(d,draft),done=progress.done;el.textContent=`必須入力 ${done} / ${progress.total} · 対象外 ${progress.excluded} · 未測定 ${progress.unmeasured}（理由記録済み） ${progress.optional}。担当・所見・使用機器は完了時に別途確認。安全判定とは別`;document.querySelector('#visit-progress-bar').style.width=(progress.total?done/progress.total*100:0)+'%';for(const e of inspectionOrder(s)){const own=checks.filter(c=>c.equipmentId===e.id),vals=own.map(c=>draft.checks[c.key]),unresolved=issuesFor(d,s.id).some(i=>i.equipmentId===e.id||!i.equipmentId);const el=document.querySelector(`[data-equipment-state="${CSS.escape(e.id)}"]`);if(el){el.textContent=unresolved||vals.includes('不具合あり')?'要対応':vals.every(x=>['正常を確認','不具合あり'].includes(x))&&(e.kind!=='蓄電池'||['soc','temp'].every(k=>draft.readings?.[k]!=null&&draft.readingConfirmed&&!draft.unavailableReasons?.[k]?.trim()))?'確認済み':'未確認';el.dataset.state=el.textContent;const icon=document.querySelector(`[data-equipment-icon="${CSS.escape(e.id)}"]`),badge=document.querySelector(`[data-icon-state="${CSS.escape(e.id)}"]`);if(icon){icon.dataset.checkState=el.textContent;icon.setAttribute('aria-label',e.kind+'の点検項目・'+el.textContent);}if(badge){badge.textContent=el.textContent;badge.dataset.state=el.textContent;}}}}
async function protect(){capture();if(!draft)return;const snapshot=structuredClone(draft);writing=writing.catch(()=>{}).then(()=>api.change(d=>{d.visitDrafts??={};d.visitDrafts[snapshot.siteId]=snapshot;},'点検入力の保護')).then(()=>{const el=document.querySelector('#draft-status');if(el)el.textContent='入力を端末内に保護しました';});try{await writing;}catch(e){const el=document.querySelector('#draft-status');if(el)el.textContent='保存失敗：'+e.message;api.toast('入力の保存に失敗しました。画面を閉じずに確認してください。');throw e;}}
