 document.addEventListener('input',e=>{if(e.target.name?.startsWith('reading-')){const checkbox=document.querySelector('[name=readingConfirmed]');if(checkbox)checkbox.checked=false;}if(e.target.closest('#solvia-visit')&&e.target.id!=='visit-photo')protect().catch(()=>{});if(e.target.id==='map-query'){query=e.target.value;pageIndex=0;const n=e.target.selectionStart;api.render();const el=document.querySelector('#map-query');el.focus();el.setSelectionRange(n,n);}if(e.target.id==='inspection-search')for(const el of document.querySelectorAll('[data-inspection-name]'))el.hidden=!el.dataset.inspectionName.toLowerCase().includes(e.target.value.toLowerCase());});
 document.addEventListener('change',async e=>{try{if(e.target.closest('#route-plan')||e.target.dataset.routeMin!==undefined){const f=document.querySelector('#route-plan'),fd=f?new FormData(f):null,el=e.target;await api.change(d=>{const p=(d.dayPlans||[]).find(x=>x.id===routeView.planId);if(!p)return;if(el.dataset.routeMin!==undefined){const raw=el.value.trim(),m=raw===''?null:Number(raw);if(m!==null&&(!Number.isInteger(m)||m<5||m>600))throw Error('作業時間は5〜600分で入れてください');p.stops[Number(el.dataset.routeMin)].minutes=m;}else{p.start=String(fd.get('start'));p.via=String(fd.get('via')||'');p.end=String(fd.get('end'));const dep=String(fd.get('departure')||'');if(/^\d\d:\d\d$/.test(dep))p.departure=dep;}},'点検する日の条件');api.render();return;}if(e.target.id==='map-region'){city='';region=e.target.value;pageIndex=0;api.render();}if(e.target.closest('#solvia-visit')&&e.target.id!=='visit-photo')await protect();if(e.target.dataset.issueState){await api.change(d=>{const i=d.sites.find(s=>s.id===e.target.dataset.issueSite).field.issues.find(i=>i.id===e.target.dataset.issueState);i.status=e.target.value;i.updatedAt=new Date().toISOString();},'不具合の対応状態変更');}if(e.target.id==='visit-photo'){capture();for(const file of e.target.files){if(file.size>8*1024*1024||draft.photos.length>=20)throw Error('写真は1枚8MB・1点検20枚までです');const src=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file);});if(!/^data:image\/(jpeg|png|webp);base64,/.test(src))throw Error('JPEG・PNG・WebPを選んでください');const eq=siteEquipment(api.data(),api.data().sites.find(s=>s.id===draft.siteId)).find(eq=>eq.id===draft.photoEquipment);draft.photos.push(src);draft.photoLinks.push({id:uid(),equipmentId:eq?.id||'',kind:eq?.kind||'',at:new Date().toISOString()});}await protect();const n=e.target.files.length;api.render();api.toast(`写真を${n}枚追加しました（下書きに保存・合計${draft.photos.length}枚）`);}if(e.target.id==='document-upload'){const f=e.target.files[0],id=e.target.dataset.document;if(!f)return;if(f.size>8*1024*1024)throw Error('添付は1ファイル8MB以下にしてください');const base64=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f);});await api.change(d=>{d.attachments??=[];d.attachments.push({id:uid(),documentId:id,name:f.name,type:f.type,data:base64,at:new Date().toISOString()});},'文書ファイルを添付');api.open('documents',id);api.toast('添付を保存しました。全体バックアップに含みます。');}}catch(error){api.toast(error.message);}});
