 if(i%6===2){const iss={id:uid(),title:'見本：'+cats[i%5]+'の確認（架空）',status:i%12===2?'確認中':'未対応',severity:'要対応',category:cats[i%5],equipmentId:s.id+(i%2?':battery':':pcs'),createdAt:ago(1+i%9)};s.field.issues.push(iss);if(i%18===8){s.field.issues.push({id:uid(),title:'見本：前に直した'+cats[i%5]+'（架空）',status:'完了',severity:'要対応',category:cats[i%5],equipmentId:iss.equipmentId,createdAt:ago(60),updatedAt:ago(50)});}if(i%4===0){s.review={at:ago(0),keys:['issue:'+iss.id],actions:{['issue:'+iss.id]:{way:ways[i%3],note:'見本の手順（架空）',due:new Date(now+((i%5)-2)*86400000).toISOString().slice(0,10),personId:d.people[0]?.id||'',at:ago(0)}}};}}
