 document.addEventListener('submit',async e=>{if(!['solvia-event','solvia-issue','solvia-location','solvia-arrival'].includes(e.target.id))return;e.preventDefault();const f=e.target,button=f.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;try{const fd=new FormData(f);if(f.id==='solvia-arrival'){const v={};for(const k of ['contact','access','parking']){const t=String(fd.get(k)||'').trim().slice(0,1000);if(t)v[k]=t;}const sid=f.dataset.site;await api.change(d=>{const s=d.sites.find(s=>s.id===sid);if(Object.keys(v).length)s.arrival={...v,updatedAt:new Date().toISOString()};else delete s.arrival;},'現場に着いたらの情報');siteInfo(sid);return;}if(f.id==='solvia-location'){const pair=(a,b)=>{const x=String(fd.get(a)||'').trim(),y=String(fd.get(b)||'').trim();if(!x&&!y)return null;const c={lat:Number(x),lon:Number(y)};if(!x||!y||!coord(c))throw Error('緯度・経度を一組で確認してください');return {...c,source:String(fd.get('source')||''),confirmedAt:new Date().toISOString()};};const c=pair('lat','lon'),entrance=pair('entranceLat','entranceLon');await api.change(d=>{const s=d.sites.find(s=>s.id===f.dataset.site);s.location=c;s.entrance=entrance;s.locationExplicit=true;},'位置・車両入口を登録');}else if(f.id==='solvia-issue'){const title=String(fd.get('title')||'').trim();if(!title)throw Error('内容を入力してください');await api.change(d=>{const s=d.sites.find(s=>s.id===f.dataset.site);s.field??={issues:[],history:[],metrics:{}};const category=String(fd.get('category')||'その他');s.field.issues.push({id:uid(),title,status:'未対応',severity:'要対応',category:CATEGORIES.includes(category)?category:'その他',createdAt:new Date().toISOString()});},'不具合追加');}else{const timing=fd.get('timing'),dt=timing==='日程未定'?'':fd.get('date'),tm=timing==='時刻付き'?fd.get('time'):'';if(timing!=='日程未定'&&!validDay(dt)||timing==='時刻付き'&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(tm))throw Error('日付と開始時刻を確認してください');await api.change(d=>{const source=f.dataset.source,id=f.dataset.id;if(source==='tasks'){const r=d.tasks.find(x=>x.id===id);r.name=fd.get('title');r.due=dt;r.eventTime=tm;r.eventTiming=timing;r.memo=fd.get('note');for(const k of ['name','due','memo'])r.touched[k]=true;}else if(source==='inspections'){const r=d.inspections.find(x=>x.id===id);r.kind=fd.get('title');r.date=dt;r.start=tm;r.eventTiming=timing;r.siteId=fd.get('siteId');r.personId=fd.get('personId');r.scheduleMemo=fd.get('note');for(const k of ['kind','date','start','siteId','personId'])r.touched[k]=true;}else{d.events??=[];const row={id,title:fd.get('title'),kind:fd.get('kind'),timing,date:dt,time:tm,siteId:fd.get('siteId'),personId:fd.get('personId'),note:fd.get('note'),done:fd.has('done')};const ix=d.events.findIndex(e=>e.id===id);if(ix<0)d.events.push(row);else d.events[ix]=row;}},'共通予定変更');}api.close();api.toast('保存しました');}catch(error){api.toast(error.message);}finally{if(button.isConnected)button.disabled=false;}});
